mapper.select:
		select 
		  sch_id as schId, /* 方案代码 */
		  sch_name as schName /* 方案名 */ 
        from BOK_SCHEME_INFO
        where scheme_type = '02'

                AND (SCH_ID like '%' || #{searchKey} || '%' 
                    OR SCH_NAME like '%' || #{searchKey} || '%')




                AND (SCH_ID like '%' || #{search} || '%' 
                    OR SCH_NAME like '%' || #{search} || '%')




                AND (SCH_ID = #{schId}
                 OR   SCH_NAME = #{schName}
                )


                AND SCH_NAME = #{schName}




                AND SCH_ID != #{owner}

select t.seq_no as seqNo, /* 流水号 */ t.sch_id as schId, /* 方案代码 */ b.IS_DEFAULT as isDefault ,/**是否默认**/ t.asset_classify as assetClassify, /* 资产分类 */ t.asset_classify as assetClassifyCode, t.capi_income_feature as capiIncomeFeature, /* 本金收益特征 */ t.capi_income_feature as capiIncomeFeatureCode, t.income_type as incomeType, /* 收入类型 */ t.income_type as incomeTypeCode, t.taxable_sign as taxableSign, /* 应税标志 - 计税方式 */ t.taxable_sign as taxableSignCode, t.fee_type as feeType, /* 免税收入类型 */ t.fee_type as feeTypeCode, t.tax_rate*100 as taxRate, /* 应税税率(%) */ TO_CHAR(t.eff_date, 'yyyy-MM-dd') as effDate/* 生效日 */ from TAX_VAT_SCHEDULE t left join BOK_SCHEME_INFO b on t.SCH_ID=b.SCH_ID
AND t.seq_no in
#{item}
AND t.SCH_ID = #{schId}
AND t.asset_classify in
#{item}
AND t.capi_income_feature in
#{item}
AND t.income_type in
#{item}
AND t.fee_type in
#{item}
and t.eff_date >= to_date(#{effDateBegin},'yyyy-mm-dd')
and t.eff_date <= to_date(#{effDateEnd},'yyyy-mm-dd')
and t.eff_date = to_date(#{effDate},'yyyy-mm-dd')
AND t.seq_no != #{owner}

select t.tax_id as taxId, /*税则代码 */ t.sch_id as schId, /* 方案代码 */ b.IS_DEFAULT as isDefault ,/**是否默认**/ t.add_tax_type as addTaxType, /* 附加税类型 */ t.add_tax_type as addTaxTypeCode, t.tax_rate*100 as taxRate, /* 应税税率(%) */ TO_CHAR(t.eff_date, 'yyyy-MM-dd') as effDate/* 生效日 */ from TAX_ADT_SCHEDULE t left join BOK_SCHEME_INFO b on t.SCH_ID=b.SCH_ID
AND t.tax_id in
#{item}
AND t.SCH_ID = #{schId}
AND t.add_tax_type in
#{item}
and t.eff_date >= to_date(#{effDateBegin},'yyyy-mm-dd')
and t.eff_date <= to_date(#{effDateEnd},'yyyy-mm-dd')
and t.eff_date = to_date(#{effDate},'yyyy-mm-dd')
AND t.tax_id != #{owner}

select tti.seq_no as seqNo, /*流水号*/ tti.sch_id as schId, /*方案代码*/ a.assetId as assetId, /*资产代码*/ a.assetName as assetName, /*资产名称*/ b.IS_DEFAULT as isDefault ,/**是否默认**/ tti.asset_classify as assetClassify, /*资产分类*/ tti.asset_classify as assetClassifyCode, tti.capi_income_feature as capiIncomeFeature, /*本金收益特征*/ tti.capi_income_feature as capiIncomeFeatureCode, tti.income_type as incomeType, /*收入类型*/ tti.income_type as incomeTypeCode, tti.taxable_sign as taxableSign, /*计税方式 - 应税标识*/ tti.taxable_sign as taxableSignCode, tti.tax_rate*100 as taxRate, /*应税税率(%)*/ TO_CHAR(tti.eff_date, 'yyyy-MM-dd') as effDate, /*生效日*/ tti.maintenance_mode as maintenanceMode, /*维护方式*/ tti.maintenance_mode as maintenanceModeCode, tti.fee_type as feeTypeCode, tti.fee_type as feeType /*免税收入类型*/ from TAX_TAXABLE_INFO tti inner join (
select nvl(fp.finprod_market_id, fp.finprod_id) as assetId, /*资产代码*/ nvl(fp.finprod_abbr, fp.finprod_name) as assetName /*资产名称*/ from fin_product_type fpt inner join fin_product fp on fp.finprod_id = fpt.finprod_id where fpt.type_3 is not null
union all
select ftp.finprod_id as assetId, /*资产代码*/ ftp.finprod_id as assetName /*资产名称*/ from fin_product_type fpt inner join fin_trade_product ftp on ftp.finprod_id = fpt.finprod_id where fpt.type_3 is not null and ftp.branch = '0'
) a on a.assetId = tti.asset_id left join BOK_SCHEME_INFO b on tti.SCH_ID=b.SCH_ID
AND tti.seq_no in
#{item}
AND tti.SCH_ID = #{schId}
AND tti.asset_classify in
#{item}
AND tti.asset_id in
#{item}
AND tti.capi_income_feature in
#{item}
AND tti.income_type in
#{item}
AND tti.taxable_sign in
#{item}
and tti.eff_date >= to_date(#{effDateBegin},'yyyy-mm-dd')
and tti.eff_date <= to_date(#{effDateEnd},'yyyy-mm-dd')
AND tti.maintenance_mode in
#{item}
and tti.eff_date = to_date(#{effDate},'yyyy-mm-dd')
AND tti.seq_no != #{owner}

select tas.scheme_type_2 as schemeType2 ,/* 参数类型 */ tas.scheme_type_2 as schemeType2Code , tas.config_id as configId ,/* 项目代码 */ b.IS_DEFAULT as isDefault ,/**是否默认**/ tas.config_name as configName ,/* 项目 */ tas.remark as remark ,/* 项目说明 */ tas.dict_code as dictCode, /* 数据字典 */ val.scheme_id as schemeId ,/* 方案代码 */ val.seq_id as seqId ,/* 代码 */ val.config_value as configValue ,/* 值 */ TO_CHAR(val.eff_date, 'yyyy-MM-dd') as effDate/*生效日*/ from bok_scheme_config tas inner join bok_scheme_config_val val on tas.config_id = val.config_id left join BOK_SCHEME_INFO b on val.SCHEME_ID = b.SCH_ID
AND seq_id in
#{item}
AND tas.config_id in
#{item}
AND tas.scheme_type_2 in
#{item}
AND val.scheme_id in
#{item}
and val.eff_date >= to_date(#{effDateBegin},'yyyy-mm-dd')
and val.eff_date <= to_date(#{effDateEnd},'yyyy-mm-dd')
and val.eff_date = to_date(#{effDate},'yyyy-mm-dd')
AND val.seq_id != #{owner}
